const params = $input.item.json.parameters;
const mensaje = $('Extraer datos del mensaje').first().json.message || '';

// Get the stored name - check both Supabase cache AND what was just saved
const nombreEnDB = $('Buscar paciente').first().json.full_name || 'Desconocido';

// Try to extract name from this message (or detect if it was given before)
let nombreDelMensaje = null;
const matchExplicit = mensaje.match(
  /(?:soy|me llamo|mi nombre es)\s+([A-Za-záéíóúÁÉÍÓÚñÑüÜ][A-Za-záéíóúÁÉÍÓÚñÑüÜ\s]{1,40}?)(?:\s*[,.]|\s+quiero|\s+quisiera|\s+deseo|\s+y\s|$)/i
);
if (matchExplicit) {
  nombreDelMensaje = matchExplicit[1].trim();
}

// Determine effective name: prefer extracted from message, then from DB
const nombreEfectivo = nombreDelMensaje || (nombreEnDB !== 'Desconocido' ? nombreEnDB : null);
const esDesconocido = !nombreEfectivo;

// If still unknown (no name anywhere), ask for name
if (esDesconocido) {
  return [{ json: { 
    needMoreInfo: true, 
    message: '¡Con gusto! ¿Me podrías decir tu nombre para poder atenderte mejor? 😊'
  }}];
}

// Has name - check if date/time provided
if (!params.date || !params.time) {
  return [{ json: { 
    needMoreInfo: true, 
    message: `¡Con gusto ${nombreEfectivo}! ¿Para qué fecha y hora prefieres tu cita? (ej: mañana a las 10 am)` 
  }}];
} else {
  return [{ json: { 
    needMoreInfo: false, 
    date: params.date, 
    time: params.time, 
    reason: params.reason 
  }}];
}

const professional = $('Buscar profesional').item.json;
// Priorizar business_config.working_hours sobre working_hours raíz
const workingHours = professional.business_config?.working_hours || professional.working_hours;

const date = new Date($input.item.json.date + 'T' + $input.item.json.time);
const day = date.toLocaleDateString('en-US', { weekday: 'long' }).toLowerCase();
const dayConfig = workingHours?.[day];

if (!dayConfig || !dayConfig.enabled) {
  // Construir lista de días disponibles para dar info útil
  const diasDisponibles = Object.entries(workingHours || {})
    .filter(([_, h]) => h.enabled)
    .map(([dia, h]) => `${dia}: ${h.start} - ${h.end}`)
    .join(', ');
  return [{ json: { 
    valid: false, 
    message: `Ese día no atendemos. Nuestros horarios disponibles son: ${diasDisponibles}.` 
  }}];
}


const traducirDia = {
  monday: 'lunes', tuesday: 'martes', wednesday: 'miércoles',
  thursday: 'jueves', friday: 'viernes', saturday: 'sábado', sunday: 'domingo'
};
const diaEspanol = traducirDia[day] || day;

const time = $input.item.json.time;
if (time < dayConfig.start || time > dayConfig.end) {
  // En el mensaje:
return [{ json: { 
  valid: false, 
  message: `Ese horario no está disponible. Los horarios del ${diaEspanol} son de ${dayConfig.start} a ${dayConfig.end}.`
}}];
}
return [{ json: { valid: true, date: $input.item.json.date, time: $input.item.json.time, reason: $input.item.json.reason }}];

