const mensaje = $('Extraer datos del mensaje').item.json.message;
const nombreActual = $('Buscar paciente').first().json.full_name;
const patientId = $('Buscar paciente').first().json.id;

// Try to extract name from common patterns
let nuevoNombre = null;
const matchLlamo = mensaje.match(/(?:soy|me llamo|mi nombre es)\s+([A-Za-záéíóúÁÉÍÓÚñÑüÜ][A-Za-záéíóúÁÉÍÓÚñÑüÜ\s]{0,30}?)(?:\s*[,.]|\s+quiero|\s+quisiera|\s+deseo|$)/i);
if (matchLlamo) {
  nuevoNombre = matchLlamo[1].trim();
}

// If no pattern match, check if message is purely a name (short, no dates/keywords)
if (!nuevoNombre) {
  const pareceNombre = mensaje &&
    mensaje.length < 40 &&
    !mensaje.match(/\d/) &&
    !mensaje.match(/mañana|hoy|lunes|martes|miércoles|jueves|viernes|sábado|domingo|cita|agendar|quiero|hola|si|no/i);
  if (pareceNombre) nuevoNombre = mensaje.trim();
}

if ((nombreActual === 'Desconocido' || !nombreActual) && nuevoNombre && patientId) {
  return [{ json: { shouldUpdate: true, newName: nuevoNombre, patientId } }];
}
return [{ json: { shouldUpdate: false, newName: nombreActual, patientId } }];

// Universal name extractor - runs for ALL intents before routing
const mensaje = $('Extraer datos del mensaje').first().json.message || '';
const nombreActual = $('Buscar paciente').first().json.full_name || 'Desconocido';
const patientId = $('Buscar paciente').first().json.id;
const esDesconocido = nombreActual === 'Desconocido' || !nombreActual;

let extractedName = null;

if (esDesconocido) {
  // Pattern: 'soy X', 'me llamo X', 'mi nombre es X'
  const matchExplicit = mensaje.match(
    /(?:soy|me llamo|mi nombre es)\s+([A-Za-záéíóúÁÉÍÓÚñÑüÜ][A-Za-záéíóúÁÉÍÓÚñÑüÜ\s]{1,40}?)(?:\s*[,.]|\s+quiero|\s+quisiera|\s+deseo|\s+y\s|$)/i
  );
  if (matchExplicit) {
    extractedName = matchExplicit[1].trim();
  }
}

// Pass through the intent classification data + name info
return [{
  json: {
    ...$input.item.json,
    patientNameToSave: extractedName || nombreActual,
    nameWasExtracted: !!extractedName,
    patientId: patientId
  }
}];

